typedef enum {
    STATE_IDLE = 0u,
    STATE_RUN = 1u,
    STATE_ERROR = 2u,
    STATE_MAX = 3u
} State_e;

static const bool transitionTable[STATE_MAX][STATE_MAX] = {
    /* IDLE */ {false, true, true},
    /* RUN */  {true, false, true},
    /* ERROR */{true, false, false}
};

typedef struct {
    State_e currentState;
    State_e previousState;
    uint32_t stateEntryTime;
} StateContext_s;

static void ExecuteEntryAction(State_e newState) {
    switch (newState) {
        case STATE_RUN:
            InitializeRun();
            break;
        default:
            break;
    }
}

static void ExecuteExitAction(State_e oldState) {
    switch (oldState) {
        case STATE_RUN:
            CleanupRun();
            break;
        default:
            break;
    }
}

void StateMachine_Reset(void) {
    context.currentState = STATE_IDLE;
    context.previousState = STATE_IDLE;
    context.stateEntryTime = 0u;
}

typedef struct {
    TopState_e topState;
    SubState_e subState;
} HierarchicalState_s;

typedef enum {
    BMS_STATEMACHINE_UNINITIALIZED = 0u,
    BMS_STATEMACHINE_INITIALIZATION = 1u,
    BMS_STATEMACHINE_STANDBY = 2u,
    BMS_STATEMACHINE_PRECHARGE = 3u,
    BMS_STATEMACHINE_NORMAL = 4u,
    BMS_STATEMACHINE_CHARGE = 5u,
    BMS_STATEMACHINE_ERROR = 6u
} BMS_STATE_e;

STD_RETURN_TYPE_e StateMachine_RequestState(State_e requestedState) {
    if (IsTransitionAllowed(currentState, requestedState)) {
        pendingRequest = requestedState;
        return STD_OK;
    }
    return STD_NOT_OK;
}

typedef enum {
    SUBSTATE_ENTRY = 0u,
    SUBSTATE_RUNNING = 1u,
    SUBSTATE_EXIT = 2u
} SubState_e;
